        if (string.IsNullOrEmpty(topic))
        {
            Console.WriteLine("No topic provided. Exiting.");
            lifetime.StopApplication();
            return;
        }

        Console.WriteLine($"\nResearching: {topic}\n");

        var aiTools = AIFunctionFactory.Create(tools);

        var agent = new ChatClientAgent(
            chatClient,
            instructions: """
                You are a thorough research assistant. Given a topic, you must:

                1. Search the web 2-3 times with different queries to gather diverse information.
                2. After each search, save key findings as notes using the SaveNote tool.
                3. After gathering enough information, retrieve all notes with GetNotes.
