            tools: [.. aiTools]);

        var runOptions = new ChatClientAgentRunOptions(new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
        });

        try
        {
            Console.WriteLine("Agent is working...\n");

            await foreach (var update in agent.RunStreamingAsync(
                $"Research the following topic and provide a comprehensive summary: {topic}",
                session: null,
                options: runOptions,
                cancellationToken: stoppingToken))
            {
                if (update.Role == ChatRole.Assistant && !string.IsNullOrEmpty(update.Text))
                {
                    Console.Write(update.Text);
                }
            }

            Console.WriteLine("\n\n=== Research Complete ===");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"\nError during research: {ex.Message}");
        }

        lifetime.StopApplication();
    }
}

