using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;
using OpenAI;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable or AI:ApiKey in configuration.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseFunctionInvocation()
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

builder.Services.AddSingleton<NoteService>();
builder.Services.AddSingleton<ResearchTools>();
builder.Services.AddHostedService<ResearchWorker>();

var app = builder.Build();
await app.RunAsync();

// --- Services ---

/// <summary>Simple in-memory store for research notes.</summary>
public sealed class NoteService
{
    private readonly List<string> _notes = [];

    public void Add(string note) => _notes.Add(note);
    public IReadOnlyList<string> GetAll() => _notes.AsReadOnly();
}

/// <summary>Tools exposed to the agent for web search and note-taking.</summary>
public sealed class ResearchTools(NoteService notes)
{
    [Description("Search the web for information on a query. Returns a list of relevant snippets.")]
    public static async Task<string> SearchWeb(
        [Description("The search query string")] string query)
    {
        // Uses Bing search scraping via a public endpoint.
        // Replace with a real search API (Bing Search, Google Custom Search) for production.
        using var http = new HttpClient();
        http.DefaultRequestHeaders.UserAgent.ParseAdd(
            "Mozilla/5.0 (compatible; ResearchAgent/1.0)");

        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";
            var html = await http.GetStringAsync(url);

            // Extract text snippets from result blocks
            var snippets = new List<string>();
            var resultSpans = html.Split("<a class=\"result__snippet\"",
                StringSplitOptions.RemoveEmptyEntries);

            foreach (var span in resultSpans.Skip(1).Take(5))
            {
                var start = span.IndexOf('>');
                var end = span.IndexOf("</a>");
                if (start >= 0 && end > start)
                {
                    var text = span[(start + 1)..end];
                    // Strip remaining HTML tags
                    text = System.Text.RegularExpressions.Regex.Replace(text, "<[^>]+>", "");
                    text = System.Net.WebUtility.HtmlDecode(text).Trim();
                    if (text.Length > 0)
                        snippets.Add(text);
                }
            }

            return snippets.Count > 0
                ? string.Join("\n\n", snippets)
                : $"No detailed snippets found for '{query}'. Try rephrasing.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Save a research note for later use in the summary.")]
    public string SaveNote(
        [Description("The note text to save")] string note)
    {
        notes.Add(note);
        return $"Note saved. You now have {notes.GetAll().Count} note(s).";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetNotes()
    {
        var all = notes.GetAll();
        return all.Count == 0
            ? "No notes saved yet."
            : string.Join("\n---\n", all);
    }
}

/// <summary>Hosted service that runs the research agent loop.</summary>
public sealed class ResearchWorker(
    IChatClient chatClient,
    ResearchTools tools,
    IHostApplicationLifetime lifetime) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        Console.WriteLine("=== Research Agent ===");
        Console.Write("Enter a research topic: ");
        var topic = Console.ReadLine()?.Trim();

        if (string.IsNullOrEmpty(topic))
        {
            Console.WriteLine("No topic provided. Exiting.");
            lifetime.StopApplication();
            return;
        }

        Console.WriteLine($"\nResearching: {topic}\n");

        var agent = new ChatClientAgent(chatClient, "ResearchAgent")
        {
            Description = "An agent that researches topics using web search and note-taking tools.",
            Instructions = """
                You are a thorough research assistant. Given a topic, you must:

                1. Search the web 2-3 times with different queries to gather diverse information.
                2. After each search, save key findings as notes using the SaveNote tool.
                3. After gathering enough information, retrieve all notes with GetNotes.
                4. Produce a well-structured summary with:
                   - An overview paragraph
                   - Key findings as bullet points
                   - A brief conclusion

                Be factual and cite specific details from your searches.
                """
        };

        var chatOptions = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
            Tools = [.. AIFunctionFactory.Create(tools)],
        };

        var agentOptions = new AgentInvokeOptions
        {
            MaximumIterations = 15,
        };

        var history = new List<ChatMessage>
        {
            new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}")
        };

        try
        {
            Console.WriteLine("Agent is working...\n");

            await foreach (var message in agent.InvokeStreamingAsync(
                history, chatOptions, agentOptions, stoppingToken))
            {
                if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
                {
                    Console.Write(message.Text);
                }
            }

            Console.WriteLine("\n\n=== Research Complete ===");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"\nError during research: {ex.Message}");
        }

        lifetime.StopApplication();
    }
}

